import sys, numpy as np, pandas as pd
from lmfit.models import LorentzianModel, LinearModel
def fit(x, y, centers):
    mod = LinearModel(prefix='bg_'); pars = mod.make_params(intercept=np.percentile(y,5), slope=0)
    for i,c in enumerate(centers):
        p = LorentzianModel(prefix=f'p{i}_'); mod = mod + p
        pars.update(p.make_params(center=c, amplitude=500, sigma=2.5))
        pars[f'p{i}_center'].set(min=c-4, max=c+4); pars[f'p{i}_sigma'].set(min=0.5, max=10); pars[f'p{i}_amplitude'].set(min=0)
    return mod.fit(y, pars, x=x)
for f,tag in [(sys.argv[1],'spot1'),(sys.argv[2],'spot2')]:
