    r1 = fit(xx,yy,[351.5]); r2 = fit(xx,yy,[351.5,355.5])
    print(tag, "E-window BIC 1-peak:", round(r1.bic,1), " 2-peak:", round(r2.bic,1), " dBIC (1-2):", round(r1.bic-r2.bic,1))
    # area = lmfit Lorentzian amplitude
    def areas(r, n):
        return {k:(round(r.params[f'p{i}_center'].value,2), round(2*r.params[f'p{i}_sigma'].value,2), round(r.params[f'p{i}_amplitude'].value,0)) for i,k in enumerate(range(n))}
    print(tag, "E-window 2-peak (center, FWHM, area):", areas(r2,2))
    # Si and A1 full-window fits quoted separately; here just print widths of narrow vs broad
